cssText:
.stage { background: radial-gradient(80vmax 60vmax at 50% 40%, var(--graphite-hi) 0%, var(--graphite) 70%); }
.hud-h, .hud-end .t { font-weight: 700; font-variation-settings: "wdth" 80, "opsz" 96; }
.hud-series { font-family: var(--font-display); letter-spacing: .12em; text-transform: uppercase; font-variation-settings: "wdth" 100, "opsz" 12; }
.hud-counter .v, .hud-scale, .hud-badge { font-variant-ligatures: none; font-feature-settings: "calt" 0, "liga" 0; }
.hud-cap { box-shadow: var(--hud-shadow); }
